import{_ as o,o as a,c as t,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"一起听音乐管线","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/music-pipeline.md","filePath":"advanced/music-pipeline.md","lastUpdated":1791051255000}'),c={name:"advanced/music-pipeline.md"};function i(s,e,n,r,l,p){return a(),t("div",null,[...e[0]||(e[0]=[d(`<h1 id="一起听音乐管线" tabindex="-1">一起听音乐管线 <a class="header-anchor" href="#一起听音乐管线" aria-label="Permalink to &quot;一起听音乐管线&quot;">​</a></h1><p>一起听音乐让房间里的成员同步播放同一首歌、同一段进度。本页说明它的服务拓扑、网易云登录态的转发规则、音频流代理的降级与防护、房间内同步算法、B站音乐的特有逻辑，以及歌词处理。</p><h2 id="服务拓扑" tabindex="-1">服务拓扑 <a class="header-anchor" href="#服务拓扑" aria-label="Permalink to &quot;服务拓扑&quot;">​</a></h2><p>音频请求由主后端代理到内嵌的网易云 API 服务，再转发到网易云上游。链路如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前端 &lt;audio&gt;</span></span>
<span class="line"><span>   │  /api/music/stream?songId=&amp;level=&amp;roomId=</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>主后端 /api/music/*</span></span>
<span class="line"><span>   │  callNcmApi()（附加 timestamp 绕内部服务 apicache）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>内部 NCM 服务 127.0.0.1:36530~36535</span></span>
<span class="line"><span>   │  @neteasecloudmusicapienhanced/api（serveNcmApi）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>网易云上游</span></span></code></pre></div><p>内嵌 NCM（网易云音乐 API 的社区实现）服务由主后端进程内嵌启动（<code>ncm-api.service.ts</code>）：绑定 <code>127.0.0.1</code>（必须显式传 host，包内 fallback 会读 <code>process.env.PORT/HOST</code>，与主服务冲突），基准端口 <strong>36530</strong> 被占用时端口号 +1 重试，最多 5 次；启动探测（HTTP 轮询就绪）总限 15s。启动失败不会阻塞主服务，此时 <code>/api/music/*</code> 返回 503 <code>NCM_UNAVAILABLE</code>。</p><p><code>callNcmApi()</code> 在每次请求上附加 <code>timestamp=Date.now()</code>。原因是内部服务挂了 2 分钟的 apicache 中间件，而缓存 key 不含 Cookie，不同登录态的相同 URL 会命中同一份缓存，匿名结果就可能被 VIP 用户取到。加上唯一时间戳即可规避。</p><h2 id="路由与登录态-api-music-ncm" tabindex="-1">路由与登录态（<code>/api/music/ncm/*</code>） <a class="header-anchor" href="#路由与登录态-api-music-ncm" aria-label="Permalink to &quot;路由与登录态（\`/api/music/ncm/*\`）&quot;">​</a></h2><p>这一组路由把前端的网易云请求转发给内嵌服务，同时管好 Cookie（服务端下发给浏览器的登录凭据）的注入与隔离。规则如下。</p><ul><li><strong>通用转发</strong>：只放行 GET/POST。服务端自动注入当前用户持久化的网易云 Cookie（<code>NcmCredential</code> 表按 userId 隔离，游客不落库），并<strong>剥离 query/body 中的 <code>cookie</code> / <code>noCookie</code> 参数</strong>，防止客户端伪造登录态。</li><li><strong>扫码登录路径</strong>（<code>/login/qr/key|create|check</code>）<strong>不注入旧凭据</strong>。网易云以请求携带的 cookie 判定登录态，带上过期的 MUSIC_U 会让二维码轮询异常（800 循环），导致扫码无效。check 成功（803）响应里的 Set-Cookie 会正常持久化，并解析 profile（昵称/头像/vipType）。</li><li><strong>Cookie 登录</strong>（<code>/api/music/ncm-cookie-login</code>）：个人中心支持直接粘贴网易云 Cookie 登录（仿 B站交互）。提交时服务端先校验 MUSIC_U 是否对应有效登录态，再持久化并同步昵称/头像缓存；过期或错误的 Cookie 返回 400。<code>GET /api/music/ncm-cookie</code> 返回 <code>MUSIC_U=xxx; __csrf=yyy</code> 格式的 Cookie 串，供「复制 Cookie」把登录态迁移到其他设备或备份。</li><li>Cookie 持久化的判定：Set-Cookie 含 <code>music_u</code>，或名称含 <code>csrf</code>。按 cookie 名去重合并，新值覆盖旧值。</li><li>VIP 归一：<code>/vip/info</code> 兜底后，10 表示 VIP、11 表示 SVIP；黑胶、音乐包、PLUS 三档会员对象也会参与有效期判定。</li><li>上游返回 3xx 时不跟随，改以 <code>{ code: &#39;REDIRECT&#39;, location }</code> 回传给前端。</li></ul><h2 id="音频流代理-api-music-stream" tabindex="-1">音频流代理 <code>/api/music/stream</code> <a class="header-anchor" href="#音频流代理-api-music-stream" aria-label="Permalink to &quot;音频流代理 \`/api/music/stream\`&quot;">​</a></h2><p>这个路由负责取到歌曲直链并交给浏览器。它要同时处理三件事：按档位降级、在没有直链可用时回退，以及挡住不该转发的地址。</p><h3 id="音质降级链" tabindex="-1">音质降级链 <a class="header-anchor" href="#音质降级链" aria-label="Permalink to &quot;音质降级链&quot;">​</a></h3><p>可用的音质档位是一条固定链条，从高到低依次尝试。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lossless → exhigh → higher → standard</span></span></code></pre></div><p>从请求档位（默认 <code>exhigh</code>）在链中的位置开始，逐档尝试 <code>/song/url/v1</code>。只有 <code>data.url</code> 非空且 <strong><code>freeTrialInfo == null</code></strong> 才算可用，试听片段与不可用同等对待。全链失败且过程中出现过试听片段时，返回 403 <code>VIP_REQUIRED</code>。</p><h3 id="回退与防护" tabindex="-1">回退与防护 <a class="header-anchor" href="#回退与防护" aria-label="Permalink to &quot;回退与防护&quot;">​</a></h3><p>音质降级链走不通时，还有这些兜底和限制。</p><ul><li><strong>v1 → 老接口回退</strong>：<code>/song/url/v1</code> 路由返回 404（内部服务依赖残缺）时，回退到 <code>/song/url</code>。level→br 的映射为 lossless 999000 / exhigh 320000 / higher 192000 / standard 128000。老接口模块依赖更少，因此依赖残缺时仍然可用。</li><li><strong>凭证回退链</strong>：当前用户 Cookie → 房主 Cookie（请求带 <code>roomId</code> 时反查 <code>Room.ownerUserId</code>），房主登录 VIP 后全房间可用。<code>&lt;audio&gt;</code> 无法携带 Authorization 头，所以 token 从 query 读取。</li><li><strong>SSRF 防护</strong>（SSRF 即服务端请求伪造，攻击者诱导服务器去访问内部地址）：解析出的直链域名必须匹配 <code>*.music.126.net</code>，否则拒绝转发。</li><li><strong>direct=1 模式</strong>：用 <strong>302 重定向</strong>把 CDN 直链交给 <code>&lt;audio&gt;</code> 直连，减少服务器带宽占用。直链缓存 <strong>15 分钟</strong>（签名实际有效期 20~30 分钟），缓存 key 包含实际生效凭证的归属，因此 VIP 直链只会发给由同一凭证链解析出的请求。<code>http:</code> 直链统一改写为 <code>https:</code>，防 mixed content。</li><li>代理流模式透传 Range（上游 206 必须转发），采用 1MB 高水位读块，客户端断连时 abort 上游并显式销毁流。</li><li>错误码：403 <code>VIP_REQUIRED</code> / 404 <code>NO_COPYRIGHT</code>（由 <code>/check/music</code> 判定）/ 502 <code>RESOLVE_FAILED</code> / 503 <code>NCM_UNAVAILABLE</code>。</li></ul><h2 id="房间内同步" tabindex="-1">房间内同步 <a class="header-anchor" href="#房间内同步" aria-label="Permalink to &quot;房间内同步&quot;">​</a></h2><p>房间里的每个成员都要看到同一首歌、同一段进度，靠的是队列持久化加一组 Socket 事件。这一节先讲队列怎么存、怎么按来源分开显示，再讲同步事件和对齐算法。</p><h3 id="队列模型-单表双源-视图过滤" tabindex="-1">队列模型：单表双源 + 视图过滤 <a class="header-anchor" href="#队列模型-单表双源-视图过滤" aria-label="Permalink to &quot;队列模型：单表双源 + 视图过滤&quot;">​</a></h3><p>队列持久化在 <code>MusicQueueItem</code> 表里，只有一张表，用 <code>source</code> 字段区分 ncm 和 bili。前端用<strong>视图过滤</strong>实现「双源独立播放列表」的语义（<code>activeQueueOf</code>）：当前曲目的 key 以 <code>bili:</code> 开头时就显示 B站列表，否则显示网易云列表。切歌和洗牌都在活动列表内推进。</p><ul><li>权威 key 有两种：<code>ncm:&lt;songId&gt;</code> 和 <code>bili:&lt;bvid&gt;:&lt;cid&gt;</code>（BV 号用正则 <code>^BV[0-9A-Za-z]{10}$</code> 校验）。</li><li><strong>封面防盗链兜底</strong>：hdslb.com 的直链在应用内会返回 403，因此 <code>setQueue</code> 统一入口把 B站封面改写为 <code>/api/stream/proxy-image</code> 代理地址。新增 B站数据源时不要存原始直链。</li><li>队列操作（upsert/remove/reorder/clear）全部走 ack（客户端回调，服务端用它回传结果）加 <code>music:queue-changed</code> 完整队列广播。<code>afterCurrent: true</code> 表示插到当前曲目之后，并右移后续条目的 order；删除后 order 会压实成 1..n。</li></ul><h3 id="同步事件与进度对齐" tabindex="-1">同步事件与进度对齐 <a class="header-anchor" href="#同步事件与进度对齐" aria-label="Permalink to &quot;同步事件与进度对齐&quot;">​</a></h3><p>下表列出房间内同步用到的 Socket 事件。</p><table tabindex="0"><thead><tr><th>事件</th><th>说明</th></tr></thead><tbody><tr><td><code>music:sync-state</code></td><td>房主→全员：<code>{trackSongId, trackKey, isPlaying, positionSec, playMode, updatedAt}</code></td></tr><tr><td><code>music:host-heartbeat</code></td><td>房主每 <strong>2s</strong>；<code>visibilitychange</code> 回前台立即补发（后台 timer 节流兜底）</td></tr><tr><td><code>music:control-request</code> / <code>music:control-response</code></td><td>观众申请 <code>pause/play/next/prev/addQueue/seek/playItem</code>；<code>from/username</code> 由服务端 socket 身份注入防伪造；seek 上限 86400s</td></tr><tr><td><code>music:sync-ack</code></td><td>观众切歌同步成功回执（房主「xx 已同步」提示）</td></tr><tr><td><code>music:get-state</code></td><td>加入房间时拉取 <code>{queue, syncState}</code>；失败退避重试 500ms×2（上限 3s）直到入房成功</td></tr></tbody></table><p>对齐算法有两条规则。</p><ul><li>观众离线判定：<strong>7s</strong> 未收到心跳即视为离线（3.5 倍间隔，容忍抖动）；页面处于 hidden 状态时跳过判定。</li><li>进度对齐：相差 <strong>&gt;2s</strong> 才 seek。传输延迟补偿为 <code>positionSec + (Date.now()-updatedAt)/1000</code>，补偿上限 <strong>10s</strong>，时钟不同源时回退原值。</li></ul><p>状态管理上还有两条约定。</p><ul><li><strong>同步状态只存内存 Map</strong>：房主离线即失效，观众随之自动进入自主控制（<code>canControl = isHost || hostOffline</code>）；队列则持久化，房间删除时清空内存态。</li><li><code>addQueue</code> 申请不走审批弹窗：房主开启「自动通过」时直接代理入队并应答，否则直接返回拒绝回执。</li></ul><h2 id="b站音乐特有逻辑" tabindex="-1">B站音乐特有逻辑 <a class="header-anchor" href="#b站音乐特有逻辑" aria-label="Permalink to &quot;B站音乐特有逻辑&quot;">​</a></h2><p>B站本身不是音乐平台，因此搜索分页、自动连播和视频背景都要单独处理。这一节说明这三处的做法。</p><h3 id="搜索分页-200-虚拟页" tabindex="-1">搜索分页（200 虚拟页） <a class="header-anchor" href="#搜索分页-200-虚拟页" aria-label="Permalink to &quot;搜索分页（200 虚拟页）&quot;">​</a></h3><p>B站单排序最多 50 页，<code>numResults</code> 封顶 1000。后端把 <strong>4 个排序分片</strong>（综合/最多点击/最多弹幕/最多收藏；「最新发布」因时间线跳变不参与）各 50 页合并为 <strong>200 虚拟页</strong>（<code>SEARCH_MAX_PAGES = 200</code>，前后端同值），按 <code>虚拟页 → (order 分片, 真实页码)</code> 做线性映射。随机模式从 1..200 的池子里随机抽页，再对当页做 Fisher-Yates 打乱。</p><h3 id="自动连播-biliautocontinue-默认开启" tabindex="-1">自动连播（<code>biliAutoContinue</code>，默认开启） <a class="header-anchor" href="#自动连播-biliautocontinue-默认开启" aria-label="Permalink to &quot;自动连播（\`biliAutoContinue\`，默认开启）&quot;">​</a></h3><p>自动连播只由用户主动点「下一首」触发。曲目自然播完不会触发，order 模式到末尾就自然停止，不回绕。链路是：<code>/api/stream/bilibili/related</code> 拉推荐 → 去重已有队列 → 取前 3 条 → <strong>倒序逐条以 <code>afterCurrent: true</code> 入队</strong>（最终顺序与推荐一致）→ 条目带 <code>recommended: true</code> 标记 → 续播第一条。拉取失败则回落为自然停止。</p><h3 id="视频背景解析链-usemusicvideobackground-ts" tabindex="-1">视频背景解析链（<code>useMusicVideoBackground.ts</code>） <a class="header-anchor" href="#视频背景解析链-usemusicvideobackground-ts" aria-label="Permalink to &quot;视频背景解析链（\`useMusicVideoBackground.ts\`）&quot;">​</a></h3><p>背景画质由 CLI 状态与设置共同决定，解析按以下优先级进行。</p><table tabindex="0"><thead><tr><th>前提</th><th>走的链路</th><th>清晰度</th></tr></thead><tbody><tr><td>CLI 开启且本地代理已连接</td><td>CLI DASH 双轨</td><td>分辨率选择指定档，<code>qn=0</code> 表示跟随账号默认（非大会员已选会员档时自动回落）</td></tr><tr><td>CLI 开启但代理未连接</td><td>服务器 MP4 直链（<code>preferMp4</code>，不回退 DASH）</td><td>固定 720P</td></tr><tr><td>CLI 关闭</td><td>「服务器 DASH 解析模式」设置决定走服务器 DASH 双轨或 MP4 直链</td><td>DASH 路径同上按分辨率选择；MP4 固定 720P</td></tr></tbody></table><p>分辨率选择（qn 参数）对 CLI DASH 与服务器 DASH 两条链路均生效；MP4 直链路径忽略该设置。B站音频直链缓存 <strong>2 小时</strong>（直链本身 1~4 小时过期）。</p><ul><li><strong>可见性门控</strong>：门控（gate）指决定某个功能是否启用的判断条件；可见性门控判断的就是画面是否已经可播。视频元素要等到 <code>canplay/playing</code>（首帧可播）才淡入，未就绪期间透出封面模糊背景——URL 就绪不等于画面就绪。</li><li><strong>进度同步</strong>：由 1s interval 命令式驱动。漂移 &gt;1.5s 时先去抖（350ms）再 seek，并进入追赶模式（<code>rate = 1 + drift/4</code>，夹在 0.6~1.5，误差 ≤0.35s 后恢复原速）；<code>readyState &lt; 3</code> 时跳过校正，防止 DASH 连续 seek 造成缓冲风暴。DASH 的时长必须显式传给引擎：容器为 mvvh 时时长读出来是 0，缺失时 <code>video.duration</code> 无效，进度同步会全部失效。</li></ul><h2 id="歌词" tabindex="-1">歌词 <a class="header-anchor" href="#歌词" aria-label="Permalink to &quot;歌词&quot;">​</a></h2><p>歌词有两个来源，展示时还允许用户微调单行时间。规则如下。</p><ul><li>网易云：<code>/api/music/ncm/lyric</code> 做三轨合并（原文/翻译/音译）；B站：走 AI 字幕接口，必须传 <code>&amp;duration=</code>，其带内校验见<a href="/advanced/video-pipeline">视频管线</a>。</li><li>单行偏移：通过右键菜单提前或延后（步长 0.5s），按 <code>songKey → lineKey</code> 持久化。显示时间 = 原时间 − 偏移，并强制单调递增，防止行序错乱。</li></ul>`,45)])])}const m=o(c,[["render",i]]);export{h as __pageData,m as default};
